--- a/cookbook/README.md
+++ b/cookbook/README.md
@@ -11,6 +11,8 @@ Copy-paste-ready code recipes for the Ollama Agent Harness. Each recipe demonstr
 | **Error Handling** | [error-handling.ts](error-handling.ts) | Typed error hierarchy (HarnessError ÔåÆ ToolExecutionError, PermissionDeniedError, etc.) with error-to-tool-result conversion and retry logic |
 | **Hello World** | [hello-world.ts](hello-world.ts) | Starter recipe |
 | **Task Loop** | [task-loop.ts](task-loop.ts) | Autonomous task execution ÔÇö reads IMPLEMENTATION_PLAN.md and works through tasks |
+| **Summarize a PDF** | [pdf-summarize.ts](pdf-summarize.ts) | Calls `PdfMetadataTool` and `PdfReadTool` from the public API, then asks Ollama to summarize the extracted text |
+| **Render a PDF page for a vision model** | [pdf-render-vision.ts](pdf-render-vision.ts) | Calls `PdfRenderPageTool` (needs `HARNESS_PDF_RENDER_COMMAND`) to rasterize a page and asks a vision model to describe it |

 ## Architecture Reference

@@ -20,3 +22,13 @@ These recipes implement patterns from the Claude Code paper:
 - **ollama-client.ts** ÔåÆ Section 3.2 (High-Level System Structure, model call interface)
 - **error-handling.ts** ÔåÆ Section 4.4 (Recovery Mechanisms)
 - **task-loop.ts** ÔåÆ Section 4.1 (The Query Pipeline, autonomous execution)
+
+## Attachments and uploads
+
+Files dragged into the chat input or uploaded via `POST /api/upload` are stored under `.harness/uploads/`. Agents and recipes interact with them through three layers:
+
+- **`list_uploads` tool.** Takes no arguments and returns each attachment as `path<TAB>size<TAB>modified`. Use it before reading any attachment when the conversation does not already include the exact path.
+- **Authoritative system block.** When the chat request includes an `attachments` array, the harness validates each entry and appends a `--- Session Attachments (authoritative) ---` block to the system prompt. The block lists every attachment with its exact `.harness/uploads/<name>` path so the model cannot lose it through paraphrasing.
+- **Uploads-aware path resolver.** `file_read`, `pdf_read`, `pdf_metadata`, `pdf_extract_tables`, `pdf_render` (input only), `image_analyze`, and `audio_transcribe` resolve through `resolveProjectReadPath`. When the model passes a bare filename that does not exist at the cwd, the resolver falls back to `.harness/uploads/<basename>` if present, emits a `PathResolution` warn log, and surfaces a `uploads_fallback` SSE event to the UI trace.
+
+The chat UI surfaces a `ÔÜá´©Å uploads fallback` trace entry whenever the resolver had to rewrite a path. Treat repeated entries from the same model as a signal to tighten its system prompt or switch to `list_uploads`.
diff --git a/cookbook/pdf-render-vision.ts b/cookbook/pdf-render-vision.ts
new file mode 100644
index 0000000..a0ac8d8
--- /dev/null
+++ b/cookbook/pdf-render-vision.ts
@@ -0,0 +1,59 @@
+/**
+ * Ollama Agent Harness ÔÇö Cookbook: Render a PDF page and ask a vision model
+ *
+ * Demonstrates calling PdfRenderPageTool to rasterize a single PDF page to
+ * PNG, then handing that image to a vision-capable Ollama model (e.g. llava)
+ * for description.
+ *
+ * Prerequisite ÔÇö set HARNESS_PDF_RENDER_COMMAND, for example:
+ *   $env:HARNESS_PDF_RENDER_COMMAND = 'pdftoppm -png -r 150 -f {page} -l {page} "{input}" "{output}"'
+ *
+ * Run with:
+ *   ts-node cookbook/pdf-render-vision.ts path/to/document.pdf 1
+ */
+
+import * as fs from 'fs/promises';
+import { Ollama } from 'ollama';
+import { PdfRenderPageTool } from '../src';
+
+async function main(): Promise<void> {
+  const target = process.argv[2];
+  const page = Number(process.argv[3] ?? '1');
+  if (!target) {
+    console.error('Usage: ts-node cookbook/pdf-render-vision.ts <path-to.pdf> [page]');
+    process.exit(1);
+  }
+
+  const render = await PdfRenderPageTool.execute({ path: target, page });
+  if (!render.success) {
+    console.error('Render failed:', render.output);
+    process.exit(1);
+  }
+  // Tool output: "Rendered page N to <relative path>"
+  const renderedPath = render.output.replace(/^Rendered page \d+ to /, '').trim();
+  console.log('--- Rendered ---');
+  console.log(renderedPath);
+
+  const imageBytes = await fs.readFile(renderedPath);
+  const model = process.env.OLLAMA_VISION_MODEL ?? 'llava';
+  const client = new Ollama({ host: process.env.OLLAMA_HOST ?? 'http://localhost:11434' });
+  const response = await client.chat({
+    model,
+    stream: false,
+    messages: [
+      {
+        role: 'user',
+        content: `Describe page ${page} of the PDF. Call out any diagrams, tables, or figures.`,
+        images: [imageBytes.toString('base64')],
+      },
+    ],
+  });
+
+  console.log('--- Vision Response ---');
+  console.log(response.message?.content ?? '(no content)');
+}
+
+main().catch((err) => {
+  console.error(err);
+  process.exit(1);
+});
diff --git a/cookbook/pdf-summarize.ts b/cookbook/pdf-summarize.ts
new file mode 100644
index 0000000..271c2ee
--- /dev/null
+++ b/cookbook/pdf-summarize.ts
@@ -0,0 +1,53 @@
+/**
+ * Ollama Agent Harness ÔÇö Cookbook: Summarize a PDF
+ *
+ * Demonstrates calling the public PdfReadTool / PdfMetadataTool APIs from a
+ * package consumer to extract text and metadata, then handing the extracted
+ * text to a chat model for summarization.
+ *
+ * Run with: ts-node cookbook/pdf-summarize.ts path/to/document.pdf
+ */
+
+import { Ollama } from 'ollama';
+import { PdfReadTool, PdfMetadataTool } from '../src';
+
+async function main(): Promise<void> {
+  const target = process.argv[2];
+  if (!target) {
+    console.error('Usage: ts-node cookbook/pdf-summarize.ts <path-to.pdf>');
+    process.exit(1);
+  }
+
+  const meta = await PdfMetadataTool.execute({ path: target });
+  if (!meta.success) {
+    console.error('Metadata read failed:', meta.error);
+    process.exit(1);
+  }
+  console.log('--- Metadata ---');
+  console.log(meta.output);
+
+  const read = await PdfReadTool.execute({ path: target, max_chars: 20_000 });
+  if (!read.success) {
+    console.error('PDF read failed:', read.error);
+    process.exit(1);
+  }
+
+  const model = process.env.OLLAMA_MODEL ?? 'llama3.1';
+  const client = new Ollama({ host: process.env.OLLAMA_HOST ?? 'http://localhost:11434' });
+  const response = await client.chat({
+    model,
+    stream: false,
+    messages: [
+      { role: 'system', content: 'Summarize the provided PDF text in 5 bullet points. Note the document title if present.' },
+      { role: 'user', content: read.output },
+    ],
+  });
+
+  console.log('\n--- Summary ---');
+  console.log(response.message?.content ?? '(no summary returned)');
+}
+
+main().catch((err) => {
+  console.error(err);
+  process.exit(1);
+});
