+    if (!response.ok) {
+      const data = await response.json().catch(() => ({}));
+      throw new Error(data.error || ('HTTP ' + response.status));
+    }
+    await loadUploadsList();
+  } catch (error) {
+    alert('Delete failed: ' + (error.message || error));
+  }
+}
